DROP TABLE IF EXISTS `knowledge_node_registry`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `knowledge_node_registry` (
  `id` bigint NOT NULL,
  `nodeCode` varchar(128) NOT NULL,
  `name` varchar(128) NOT NULL,
  `nodeType` varchar(32) NOT NULL,
  `description` text,
  `aliasesJson` json DEFAULT NULL,
  `homeSectionCode` varchar(128) DEFAULT NULL,
  `sourceRefsJson` json DEFAULT NULL,
  `layer` varchar(32) DEFAULT NULL,
  `createTime` datetime DEFAULT CURRENT_TIMESTAMP,
  `updateTime` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `isDelete` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `nodeCode` (`nodeCode`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
