DROP TABLE IF EXISTS `learning_unit`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `learning_unit` (
  `id` bigint NOT NULL,
  `unitCode` varchar(128) NOT NULL,
  `courseCode` varchar(128) NOT NULL,
  `sectionCode` varchar(128) NOT NULL,
  `title` varchar(200) NOT NULL,
  `sortOrder` int NOT NULL DEFAULT '0',
  `estimatedMinutes` int NOT NULL DEFAULT '0',
  `revision` int NOT NULL DEFAULT '1',
  `reviewStatus` varchar(16) NOT NULL DEFAULT 'DRAFT',
  `draftJson` json NOT NULL,
  `publishedJson` json DEFAULT NULL,
  `userId` bigint NOT NULL,
  `contributor` varchar(64) DEFAULT NULL,
  `createTime` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updateTime` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `isDelete` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `unitCode` (`unitCode`),
  KEY `idx_unit_course` (`courseCode`,`sortOrder`),
  KEY `idx_unit_section` (`sectionCode`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

